import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { get_asset_distributors } from "@/mixins/GetAssetDistributors.js";
import { get_asset_reatilers } from "@/mixins/GetAssetRetailers.js";
export default {
  mixins: [get_asset_distributors, get_asset_reatilers],
  props: {
    assetdisplay: Boolean,
    adminassetItems: Object
  },
  data() {
    return {
      organization_currency: ""
    };
  },
  watch: {
    assetdisplay: {
      async handler() {
        if (this.assetdisplay == true) {
          this.organization_currency = this.$store.getters.GetUserObj.organization.organization_currency == undefined ? "" : this.$store.getters.GetUserObj.organization.organization_currency;

          // Fetch distributor and retailer lists if external type is DISTRIBUTOR or RETAILER
          if (this.adminassetItems.asset_handler_type === "EXTERNAL" && (this.adminassetItems.asset_external_handler_type === "DISTRIBUTOR" || this.adminassetItems.asset_external_handler_type === "RETAILER")) {
            await Promise.all([this.get_asset_distributors(), this.get_asset_reatilers()]);
          }

          // console.log(this.adminassetItems);
        }
      },
      immediate: true
    }
  },
  methods: {
    formatDate(asset_purchased_date) {
      const date = new Date(asset_purchased_date);
      return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate() + 1).padStart(2, "0")}`;
    },
    formate_date(value) {
      if (value == "N/A" || !value || value == null || value == undefined) {
        return value == "N/A" ? value : "-";
      }
      var data = formatdisplayDate(value);
      return data;
    },
    formatAssetCondition(value) {
      if (!value || value == null || value == undefined) {
        return "-";
      }
      const conditionMap = {
        NEW: "New",
        OLD: "Old",
        NEW_WAREHOUSE: "New Warehouse",
        OLD_WAREHOUSE: "Old Warehouse"
      };
      return conditionMap[value] || value;
    },
    formatShipmentStatus(value) {
      if (!value || value == null || value == undefined) {
        return "-";
      }
      const statusMap = {
        WAREHOUSE: "Warehouse",
        INSTOCK: "Warehouse",
        DELIVERED: "Delivered",
        PENDING: "Pending",
        RECEIVED: "Received"
      };
      return statusMap[value] || value;
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    getManagedByName() {
      const managedById = this.adminassetItems.asset_assined_to || this.adminassetItems.last_assigned_to;
      if (!managedById) {
        return "-";
      }

      // If internal, return as is (it's already a name/email)
      if (this.adminassetItems.asset_handler_type !== "EXTERNAL") {
        return managedById;
      }

      // If external type is DISTRIBUTOR, find name from distributor list
      if (this.adminassetItems.asset_external_handler_type === "DISTRIBUTOR") {
        if (this.masterAssetDistributors && Array.isArray(this.masterAssetDistributors)) {
          const distributor = this.masterAssetDistributors.find(dist => dist.asset_distributor_id === managedById || dist.asset_distributor_email_id === managedById || dist.distributor_email_id === managedById || dist.email_id === managedById);
          if (distributor) {
            return distributor.asset_distributor_name || distributor.distributor_name || distributor.name || managedById;
          }
        }
        return managedById;
      }

      // If external type is RETAILER, find name from retailer list
      if (this.adminassetItems.asset_external_handler_type === "RETAILER") {
        if (this.masterAssetRetailers && Array.isArray(this.masterAssetRetailers)) {
          const retailer = this.masterAssetRetailers.find(ret => ret.asset_retailer_id === managedById || ret.asset_retailer_email_id === managedById || ret.retailer_email_id === managedById || ret.email_id === managedById);
          if (retailer) {
            return retailer.asset_retailer_name || retailer.retailer_name || retailer.name || managedById;
          }
        }
        return managedById;
      }

      // For CUSTOMER or other types, return as is
      return managedById;
    }
  }
};
